// Simple Neon Grid Runner – targets <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = 400;
  const H = canvas.height = 600;

  const LANE_COUNT = 3;
  const LANE_WIDTH = W / LANE_COUNT;
  const PLAYER_RADIUS = 8;
  const PLAYER_Y = H - 50; // fixed vertical position

  let playerLane = 1; // 0‑left,1‑mid,2‑right
  let obstacles = [];
  let score = 0;
  let gameOver = false;
  let lastSpawn = 0;
  const SPAWN_INTERVAL = 800; // ms

  // Input handling
  const move = dir => { playerLane = Math.max(0, Math.min(LANE_COUNT - 1, playerLane + dir)); };
  window.addEventListener('keydown', e => {
    if (e.key === 'ArrowLeft') move(-1);
    else if (e.key === 'ArrowRight') move(1);
    else if (e.key === ' ') e.preventDefault(); // prevent scroll
  });

  // Simple touch – taps on left/right half of canvas
  canvas.addEventListener('click', e => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    move(x < W / 2 ? -1 : 1);
  });

  const spawnObstacle = () => {
    const lane = Math.floor(Math.random() * LANE_COUNT);
    obstacles.push({ lane, y: -20, size: 20 });
  };

  const update = dt => {
    if (gameOver) return;
    // spawn
    const now = performance.now();
    if (now - lastSpawn > SPAWN_INTERVAL) { spawnObstacle(); lastSpawn = now; }
    // move obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.y += dt * 0.2; // speed
      // collision (simple circle‑square check)      
      const playerX = playerLane * LANE_WIDTH + LANE_WIDTH / 2;
      if (o.lane === playerLane && Math.abs(o.y - PLAYER_Y) < PLAYER_RADIUS + o.size / 2) {
        gameOver = true;
        break;
      }
      // remove off‑screen
      if (o.y - o.size > H) { obstacles.splice(i, 1); score++; }
    }
  };

  const draw = () => {
    // background gradient neon grid
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, W, H);
    // grid lines
    ctx.strokeStyle = '#0ff';
    ctx.lineWidth = 1;
    for (let i = 0; i <= LANE_COUNT; i++) {
      const x = i * LANE_WIDTH;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, H);
      ctx.stroke();
    }
    // player dot
    ctx.fillStyle = '#0f0';
    const px = playerLane * LANE_WIDTH + LANE_WIDTH / 2;
    ctx.beginPath();
    ctx.arc(px, PLAYER_Y, PLAYER_RADIUS, 0, Math.PI * 2);
    ctx.fill();
    // obstacles (spikes)
    ctx.fillStyle = '#f00';
    obstacles.forEach(o => {
      const x = o.lane * LANE_WIDTH + LANE_WIDTH / 2;
      ctx.fillRect(x - o.size / 2, o.y - o.size / 2, o.size, o.size);
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px monospace';
    ctx.fillText('Score: ' + score, 10, 20);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '36px monospace';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  };

  let last = performance.now();
  const loop = () => {
    const now = performance.now();
    const dt = now - last;
    last = now;
    update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  requestAnimationFrame(loop);
})();
